import os
import requests
import json

# Initialize variables
host = os.environ.get('DATABRICKS_HOST')
if not host.startswith('https://'):
    host = f'https://{host}'
token = os.environ.get('DATABRICKS_TOKEN')
prefix = os.environ.get('MLPAB_DATABRICKS_PREFIX', 'mlpab5a6a7b')
user = 'benedict@logicalclocks.com'

# Define paths
env_path = f'/Users/{user}/{prefix}/environment.yml'

# Create a minimal environment YAML
env_yaml = '''
name: minimal_env
channels:
  - defaults
dependencies:
  - python=3.9
'''

# Upload the environment YAML using the workspace import API
url = f'{host}/api/2.1/workspace/import'
headers = {
    'Authorization': f'Bearer {token}',
    'Content-Type': 'application/json'
}

payload = {
    'path': env_path,
    'content': env_yaml.encode('utf-8').hex(),
    'language': 'PYTHON',
    'overwrite': True,
    'format': 'AUTO'
}

response = requests.post(url, headers=headers, data=json.dumps(payload))
if response.status_code == 200:
    print(f'Uploaded environment YAML to: {env_path}')

    # Define job name and workspace path
    job_name = f'{prefix}_flaky9ff0fe'
    workspace_path = f'/Users/{user}/{prefix}/failing_job.py'

    # Define the job payload
    job_payload = {
        'name': job_name,
        'tasks': [
            {
                'task_key': 'flaky_task',
                'spark_python_task': {
                    'python_file': workspace_path
                },
                'email_notifications': {
                    'on_failure': [user]
                },
                'environment_key': 'serverless_env'
            }
        ],
        'email_notifications': {
            'on_failure': [user]
        },
        'environments': [
            {
                'environment_key': 'serverless_env',
                'spec': {
                    'base_environment': env_path
                }
            }
        ]
    }

    # Send the request to create the job
    job_url = f'{host}/api/2.1/jobs/create'
    job_response = requests.post(job_url, headers=headers, data=json.dumps(job_payload))

    if job_response.status_code == 200:
        job = job_response.json()
        job_id = job['job_id']

        # Run the job once
        run_url = f'{host}/api/2.1/jobs/run-now'
        run_payload = {'job_id': job_id}
        run_response = requests.post(run_url, headers=headers, data=json.dumps(run_payload))

        if run_response.status_code == 200:
            run = run_response.json()
            print(f'Job created: {job_name} (ID: {job_id})')
            print(f'Alert configured: Email notification for failures (mentions flaky9ff0fe)')
            print(f'Run started: {run[\"run_id\"]}')
        else:
            print(f'Failed to start job: {run_response.text}')
    else:
        print(f'Failed to create job: {job_response.text}')
else:
    print(f'Failed to upload environment YAML: {response.text}')
"

